import{_ as e,o as a,c as i,ag as d}from"./chunks/framework.DyxC4IQh.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"VimAct","text":"让键盘点遍 Android","tagline":"任意 App 里的可点击元素都会贴上标签，敲一两个字母就完成点击。不用 root，不联网。","actions":[{"theme":"brand","text":"开始使用","link":"/guide/install.html"},{"theme":"alt","text":"下载","link":"/download.html"},{"theme":"alt","text":"键位一览","link":"/guide/keys.html"}]},"features":[{"title":"一个键进，Esc 出","details":"按一下 F，屏幕上的可点击元素逐个贴上标签；敲标签字母，点下去，覆盖层自动消失。"},{"title":"不需要 root，也不需要录屏权限","details":"走系统无障碍服务（AccessibilityService）读屏幕、贴覆盖层。不注入进程，不申请 MediaProjection，不依赖常驻 ADB。"},{"title":"标签跟着屏幕走","details":"hint 模式每 32 毫秒重扫一次。滚动或局部刷新后，同一个元素的标签尽量保持不变，不会满屏乱跳。"},{"title":"打字的时候它不插手","details":"输入法弹出时所有标签和光标立即收起，按键完全交回 IME。没进 hint 模式时，VimAct 也只认自己那几个键（方向键、光标点击键、通知键、触发键），其余一律放行。跟别的改键应用一起用之前，先确认键位没撞上，常见问题里有说明。"},{"title":"不想记标签，就用方向键","details":"WASD 或 HJKL 驱动一个空间光标，每次按键按屏幕几何走到那个方向上折算距离最近的一个元素，容器和容器里的元素都在同一张候选表里。"},{"title":"本地优先","details":"APK 不申请 INTERNET 权限，没有遥测和分析 SDK。无障碍服务能看到的屏幕内容，全部只在设备上处理。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1793279156000}'),l={name:"index.md"};function r(o,t,n,h,s,c){return a(),i("div",null,[...t[0]||(t[0]=[d('<h2 id="它解决什么" tabindex="-1">它解决什么 <a class="header-anchor" href="#它解决什么" aria-label="Permalink to &quot;它解决什么&quot;">​</a></h2><p>Android 的交互原语是触摸。接上物理键盘以后，这个前提就露了馅：没有全局的键盘导航，焦点陷阱一大堆，很多控件根本不可聚焦。结果是你在「键盘打字」和「伸手点击」之间反复横跳。</p><p>VimAct 把点击重新变成键盘可寻址的目标。触发一次，屏幕上所有可点击元素贴上标签，敲标签就完成点击。参照物是浏览器里的 Vimium，只是范围换成了整个 Android。</p><h2 id="三条路径" tabindex="-1">三条路径 <a class="header-anchor" href="#三条路径" aria-label="Permalink to &quot;三条路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想做什么</th><th>用什么</th></tr></thead><tbody><tr><td>明确知道要点哪个元素</td><td><a href="/vimact-site/guide/hints.html">Hint 标签点击</a>，敲标签直达</td></tr><tr><td>屏幕上目标太密、懒得找标签</td><td><a href="/vimact-site/guide/cursor.html">方向键光标</a>，WASD/HJKL 走到框上再点</td></tr><tr><td>只想把弹出来的通知点开或划掉</td><td><a href="/vimact-site/guide/notification.html">通知栏一键</a>，一个键搞定</td></tr></tbody></table><h2 id="能跑在哪" tabindex="-1">能跑在哪 <a class="header-anchor" href="#能跑在哪" aria-label="Permalink to &quot;能跑在哪&quot;">​</a></h2><ul><li>Android 10（API 29）及以上，物理键盘：蓝牙、USB、折叠屏或平板的内置键盘都算。</li><li>系统 UI 和第三方 App 均覆盖；WebView 里的内容按无障碍树能暴露多少算多少，不保证全覆盖。</li><li>Samsung DeX 那一类桌面模式不用额外配置：外接的本来就是键盘和大屏。</li></ul><h2 id="现在到哪一步" tabindex="-1">现在到哪一步 <a class="header-anchor" href="#现在到哪一步" aria-label="Permalink to &quot;现在到哪一步&quot;">​</a></h2><p>v0.1 只交付上面那条闭环：触发、扫描、贴标签、输入标签、点击、消失。设置界面管键位选择、方向键开关和排除应用，没有别的功能入口。</p><p>以下都在计划里，当前版本做不到：长按 hint、<code>/search</code> 文本过滤、三字符以上标签、自定义字符集、按 App 定制 hint 规则、分屏与多窗口的行为保证。</p><p>真机验证还没开始，<code>onKeyEvent</code> 在各家 OEM ROM 上的兼容性是首要风险项，所以渠道划分比较保守，见<a href="/vimact-site/download.html">下载</a>。</p><p>第一枚对外产物已经挂出来：测试版 <code>0.1.0-mvp-beta</code>，按 CPU 架构分三枚包。这一轮测试版没等真机结论就发了，正式版仍然要等；装上以后遇到问题，欢迎到 Release 页面回话。</p>',12)])])}const u=e(l,[["render",r]]);export{p as __pageData,u as default};
